widget.solution:
def smallest_true(lo, hi, pred):
    a, b = lo, hi + 1
    while a < b:
        mid = (a + b) // 2
        if pred(mid):
            b = mid
        else:
            a = mid + 1
    return a if a <= hi else None


def max_size(limit, risk, hi):
    first_bad = smallest_true(0, hi, lambda n: risk(n) > limit)
    if first_bad is None:
        return hi
    if first_bad == 0:
        return None
    return first_bad - 1
